import{z as A,x as E,o as r,c as p,q as t,j as o,D as e,d as i,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"动态规划","description":"","frontmatter":{"title":"动态规划","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dynamic-programming.md","filePath":"cs/dynamic-programming.md","lastUpdated":1791413859000}'),d={name:"cs/dynamic-programming.md"};function m(B,a,c,h,_,D){const n=E("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="动态规划" tabindex="-1">动态规划 <a class="header-anchor" href="#动态规划" aria-label="Permalink to &quot;动态规划&quot;">​</a></h1><div class="epigraph"><p>最优子结构加上重叠子问题：把子答案制成表，每个状态只算一次。</p><footer>—— 据 Bellman, Dynamic Programming, 1957；CLRS 第 15 章整理</footer></div><p>上一课<a href="/cs/exchange-argument">交换论证</a>要求证明「只走一条局部选择」。本课不重做交换论证。缺口是：最优子结构仍在，但<strong>哪一条选择对事先不知道</strong>，且同一子问题被多次引用。分治若直接递归会指数爆炸。本课钉 DP：状态、转移、填表或备忘。Floyd 已是实例，这里抽象出来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>钢条切割、最长公共子序列：最优解包含某子问题的最优解，但切点或对齐位置有多种，必须都试。朴素递归树里 \\(T(i)\\) 与 \\(T(j)\\) 反复出现。缺口不是再发明递归，而是<strong>用空间换重复计算</strong>：每个状态 \\(\\Theta(1)\\) 或多项式次转移。</p>',5)),(r(),o(l,null,{default:e(()=>[s(n,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20F5%5B%22%E7%AE%97%20F(5)%22%5D%20--%3E%20F4%5B%22F(4)%22%5D%0A%20%20F5%20--%3E%20F3a%5B%22F(3)%22%5D%0A%20%20F4%20--%3E%20F3b%5B%22F(3)%EF%BC%9A%E7%AC%AC%202%20%E6%AC%A1%22%5D%0A%20%20F4%20--%3E%20F2a%5B%22F(2)%22%5D%0A%20%20F3a%20--%3E%20F2b%5B%22F(2)%EF%BC%9A%E7%AC%AC%202%20%E6%AC%A1%22%5D%0A%20%20F3b%20--%3E%20F2c%5B%22F(2)%EF%BC%9A%E7%AC%AC%203%20%E6%AC%A1%22%5D%0A%20%20MEM%5B%22%E5%A4%87%E5%BF%98%EF%BC%9A%E6%AF%8F%E4%B8%AA%20F(k)%20%E5%8F%AA%E7%AE%97%E4%B8%80%E6%AC%A1%EF%BC%8C%E5%85%B6%E4%BD%99%E7%9B%B4%E6%8E%A5%E6%9F%A5%E8%A1%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">备忘可以类比做卷子时在草稿边记下小题答案：同一道小题第二次遇到，直接抄结果不再重做。DP 的填表把这件事系统化——先把所有小题按依赖顺序排好，每题只做一次，最大的那题自然就有解了。图的下半句就是「重叠子问题」五个字的全部含义。</span></p><p>与分治对照：分治子问题几乎不交；DP 故意交。与贪心对照：贪心省掉除一条以外的转移。三者都要最优子结构；只有 DP 默认枚举。</p><h3 id="状态不是「再开一个数组」" tabindex="-1">状态不是「再开一个数组」 <a class="header-anchor" href="#状态不是「再开一个数组」" aria-label="Permalink to &quot;状态不是「再开一个数组」&quot;">​</a></h3><p>先定义「子问题是什么」（前缀、区间、到顶点 \\(v\\) 且用了 \\(k\\) 条边）。再写转移。没有状态就没有表。本课不把背包容量细节写完，那是下一课；这里用钢条或 LCS 当骨架。</p><p><span class="marginnote">Bellman 1957 的「最优化原理」即最优子结构。CLRS 第 15 章用备忘与自底向上对照。本课两者都承认：拓扑序填表 = 带缓存的递归。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义状态 \\(dp[\\cdot]\\)。写出边界与转移（\\(\\min\\) 或 \\(\\max\\) 若干更小状态）。证明每个状态依赖的规模更小，故 DAG 上可算——<a href="/cs/dag-repr">DAG</a> 与<a href="/cs/topo-sort">拓扑</a>在这里变成填表序。复杂度 = 状态数 \\(\\times\\) 转移代价。</p>',7)),(r(),o(l,null,{default:e(()=>[s(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E5%AE%9A%E4%B9%89%E7%8A%B6%E6%80%81%22%5D%20--%3E%20REC%5B%22%E8%BD%AC%E7%A7%BB%EF%BC%9A%E6%9E%9A%E4%B8%BE%E9%80%89%E6%8B%A9%22%5D%0A%20%20REC%20--%3E%20TAB%5B%22%E6%8C%89%E4%BE%9D%E8%B5%96%20DAG%20%E5%A1%AB%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20ANS%5B%22%E5%8E%9F%E9%97%AE%E9%A2%98%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>重建解要存前驱选择，不只存数值。本课点名。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>时间多项式当状态多项式。指数状态（子集 DP 的 \\(2^n\\)）仍可能有用，但是否在 P 要另说——<a href="/cs/p-vs-np">P 与 NP</a> 才划分。本课算法课内默认多项式状态的例子。</p><p>Floyd 的 \\(k,i,j\\) 是三维状态；最短路的「按边数」是 Bellman–Ford 的 DP 读法。本课把它们收进同一句话，不再各写一章定义。</p><p><span class="marginnote">重复的代价代个数：朴素递归算 F(30) 要约 270 万次函数调用，其中 F(2) 这一个状态就被重算 50 多万次；带备忘的版本只需 30 次加法。指数与多项式的差距，就是「同一状态算一次」和「每次引用都重算」的差距。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有最优子结构就不要 DP（有环最长简单路）。没有重叠则备忘无收益，退回分治。贪心若已证，DP 仍正确但更慢。本课不引入凸优化加速。</p><p><span class="marginnote">初学者容易以为「DP 就是开数组」。状态才是本体，数组只是容器：状态定义漏掉一个维度（比如「到顶点 \\(v\\)」没记「用了几条边」），转移写得再漂亮也算不出正确答案。定义状态时问自己：要让子问题独立作答，还缺哪些信息？缺的就是要加的维度。</span></p><p>后课默认：DP = 状态 + 转移 + 填表。0-1 与完全背包是下一课把容量做成状态的实例。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DP 用于最优子结构 + 重叠子问题；枚举选择并缓存。</li><li>填表序是子问题 DAG 的拓扑。</li><li>贪心是「可证只留一条转移」的特例。</li><li>出处：Bellman, 1957；CLRS 第 15 章。</li></ul>',11))])}const P=A(d,[["render",m]]);export{C as __pageData,P as default};
